#!/usr/bin/env python3
"""V44 — causal decomposition of slow-memory capacity failure.

Mac M3 scientific run (recommended): use RUN_V44_M3.command, which wraps this
process in macOS caffeinate and fixes BLAS to one thread per worker.

Direct commands:
  python3 elm_v44_capacity_diagnosis.py --self-test
  python3 elm_v44_capacity_diagnosis.py --engineering --out-dir v44_results
  python3 elm_v44_capacity_diagnosis.py --stage causal --out-dir v44_results
  python3 elm_v44_capacity_diagnosis.py --stage forensic --out-dir v44_results
  python3 elm_v44_capacity_diagnosis.py --stage all --out-dir v44_results

The scientific manipulation is exactly the locked V44 2x2 resource intervention:
CAP-BASE (T=512,C=384), TRACE-RELIEF (T nonbinding,C=384),
SLOT-RELIEF (T=512,C nonbinding), BOTH-RELIEF (both nonbinding).
No eviction/admission rule is changed.
"""
from __future__ import annotations

import argparse, base64, collections, concurrent.futures, contextlib, csv, dataclasses
import fcntl, gzip, hashlib, io, json, math, os, pickle, platform, shutil, signal
import statistics, sys, tempfile, time, types, zipfile, zlib
from pathlib import Path

# M3/Accelerate and other BLAS backends: seed workers are the parallel unit.
for _k in ('OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','OMP_NUM_THREADS',
           'VECLIB_MAXIMUM_THREADS','NUMEXPR_NUM_THREADS'):
    os.environ[_k] = '1'
os.environ.setdefault('PYTHONUNBUFFERED','1')

VERSION = 'V44-capacity-causal-decomposition-1.0'
SOURCE = Path(__file__).resolve()
SCIENCE_SEEDS = tuple(range(43101, 43117))
ENGINEERING_SEEDS = (944001, 944002)
FORENSIC_LOADS = (64, 128, 256, 512)
CAUSAL_LOAD = 256
REPEATS = 8
TRACE_CAP = 512
SLOT_CAP = 384
NONBINDING_CAP = 1_000_000_000
CHECKPOINT_RECORDS_DEFAULT = 128
BRANCHES = ('CAP-BASE','TRACE-RELIEF','SLOT-RELIEF','BOTH-RELIEF')
READ_POLICIES = ('SUPER','SILENT-HARD','FIXED-50','LOCAL-BAYES-0')
MATERIAL = 0.05
V39_SHA256 = '229acfe264f40a0647aede5b7301a05d09c4ea81743748a17216a1de544103e9'
DESIGN_SHA256 = '7e7926e5ec47f90bbd94717bdb23e5f6daebc077088a568592682ec87f3be3fb'

V39_PAYLOAD = ''
DESIGN_PAYLOAD = ''

_np = None
_student_t = None
V39 = None


def ensure_deps(install=False):
    global _np, _student_t, V39
    try:
        import numpy as np
        from scipy.stats import t as student_t
    except ImportError:
        if not install:
            raise SystemExit('V44 needs NumPy and SciPy. Run with --install-deps or use RUN_V44_M3.command.')
        import subprocess
        subprocess.run([sys.executable,'-m','pip','install','numpy>=1.26','scipy>=1.11'], check=True)
        import numpy as np
        from scipy.stats import t as student_t
    _np, _student_t = np, student_t
    if V39 is None:
        raw = zlib.decompress(base64.b64decode(V39_PAYLOAD))
        if hashlib.sha256(raw).hexdigest() != V39_SHA256:
            raise RuntimeError('Embedded V39 source hash mismatch.')
        mod = types.ModuleType('v44_embedded_v39')
        mod.__file__ = '<embedded-v39>'
        sys.modules[mod.__name__] = mod
        exec(compile(raw, mod.__file__, 'exec'), mod.__dict__)
        mod.np = np
        mod.student_t = student_t
        V39 = mod
    return np


def design_text():
    raw = zlib.decompress(base64.b64decode(DESIGN_PAYLOAD))
    if hashlib.sha256(raw).hexdigest() != DESIGN_SHA256:
        raise RuntimeError('Embedded V44 design hash mismatch.')
    return raw.decode()


def sha_bytes(b): return hashlib.sha256(b).hexdigest()
def sha_json(x): return sha_bytes(json.dumps(x, sort_keys=True, separators=(',',':'), default=str).encode())
def source_sha(): return sha_bytes(SOURCE.read_bytes())


def atomic_bytes(path, data):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f'.tmp-{os.getpid()}')
    with tmp.open('wb') as f:
        f.write(data); f.flush(); os.fsync(f.fileno())
    os.replace(tmp, path)


def atomic_text(path, text): atomic_bytes(path, text.encode())
def write_json(path, x): atomic_text(path, json.dumps(x, indent=2, sort_keys=True, default=str)+'\n')


def branch_caps(name):
    if name == 'CAP-BASE': return TRACE_CAP, SLOT_CAP
    if name == 'TRACE-RELIEF': return NONBINDING_CAP, SLOT_CAP
    if name == 'SLOT-RELIEF': return TRACE_CAP, NONBINDING_CAP
    if name == 'BOTH-RELIEF': return NONBINDING_CAP, NONBINDING_CAP
    raise ValueError(name)


def make_stream(seed, load, repeats=REPEATS, smoke=False):
    """Exact V40/V41 load-generalized generator, at V43's repeats=8.

    Load is total identities, hence keys_per_wave=load//4.  No clutter tail.
    """
    np = _np
    rr = np.random.default_rng(seed + 810007)
    count = (4 if smoke else load // 4)
    reps = (2 if smoke else repeats)
    waves = 4
    key_alphabet = np.frombuffer(b'0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ', dtype=np.uint8)
    keys=[]
    while len(keys) < count*waves:
        key=bytes(rr.choice(key_alphabet,size=6))
        if key not in keys: keys.append(key)
    labels=rr.choice(np.frombuffer(b'abcdefghijklmnopqrstuvwx',dtype=np.uint8),size=len(keys)).astype(int)
    nrev=max(1,count//4)
    revised=list(range(nrev)); noisy=list(range(nrev,2*nrev)); untouched=list(range(2*nrev,count))
    changed={i:int(ord('a')+(int(labels[i])-ord('a')+1+int(rr.integers(23)))%24) for i in revised}
    rows=[]; checkpoints=[]; render_counts=collections.Counter()
    def add(i,target,kind,exposure,wave,alias):
        render_counts[(i,alias,kind)] += 1
        rows.append({'key_id':int(i),'target':int(target),'kind':kind,'exposure':int(exposure),
                     'wave':wave,'alias':int(alias),'rendering_exposure':render_counts[(i,alias,kind)],
                     'raw':V39.context(keys[i],alias)+bytes([target])+b'\n'})
    for wave in range(waves):
        cohort=chr(65+wave)
        for exposure in range(1,reps+1):
            for i in rr.permutation(np.arange(wave*count,(wave+1)*count)):
                add(int(i),int(labels[i]),'acquisition',exposure,cohort,(exposure-1)%2)
            # V43 Q0 needs acquisition checkpoints, not only end-of-wave.
            if exposure in tuple(x for x in (1,2,4,8) if x <= reps):
                checkpoints.append({'record_count':len(rows),'name':f'{cohort}_acq_{exposure}',
                                    'type':'acquisition','wave':cohort,'exposure':exposure})
        checkpoints.append({'record_count':len(rows),'name':f'after_{cohort}','type':'wave','wave':cohort})
        if wave == 1:
            for i in noisy:
                wrong=ord('a')+(int(labels[i])-ord('a')+1)%24
                add(i,wrong,'one_off_noise',1,cohort,0)
        if wave == 2:
            for exposure in range(1,9 if not smoke else 3):
                for i in rr.permutation(revised): add(int(i),changed[int(i)],'revision',exposure,cohort,0)
                if exposure in (1,2,4,8):
                    checkpoints.append({'record_count':len(rows),'name':f'revision_{exposure}',
                                        'type':'revision','wave':cohort,'exposure':exposure})
    raw=b''.join(r['raw'] for r in rows)
    assert all(len(r['raw'])==14 for r in rows)
    return {'seed':seed,'load':load,'keys':keys,'labels':labels,'revised':revised,'noisy':noisy,
            'untouched':untouched,'revisions':changed,'rows':rows,'raw':raw,'checkpoints':checkpoints,
            'keys_per_wave':count,'repeats':reps,'raw_sha256':sha_bytes(raw)}


class SuperposedLayer:
    """V40 stationary S2-lag-c12 fast layer; prediction and write separated."""
    UNITS=4096; K=205; CONTACTS=12; OUTPUTS=256; RATE=.6
    def __init__(self, seed):
        np=_np
        rr=np.random.default_rng(seed+3604096)
        self.contacts=np.array([rr.choice(96,self.CONTACTS,replace=False) for _ in range(self.UNITS)])
        self.weights=rr.normal(size=(self.UNITS,self.CONTACTS))
        self.weights/=np.linalg.norm(self.weights,axis=1,keepdims=True)
        self.encoder=V39.Encoder(seed,'lag')
        self.output=np.zeros((self.UNITS,self.OUTPUTS))
        self.ops=0; self.updates=0
    def encode(self, window):
        np=_np
        z=self.encoder.encode(bytes(window))[0]
        u=np.tanh(np.einsum('ij,ij->i',self.weights,z[self.contacts]))
        ix=np.sort(np.argpartition(-np.abs(u),self.K-1)[:self.K]); vals=u[ix]
        n=float(np.linalg.norm(vals)); return ix,(vals/n if n>1e-12 else np.zeros(self.K))
    def predict(self, window, count_ops=True):
        ix,v=self.encode(window)
        if count_ops: self.ops += self.K*self.OUTPUTS + self.UNITS*self.CONTACTS + self.UNITS
        return v @ self.output[ix]
    def observe(self, window, y):
        np=_np
        ix,v=self.encode(window); block=self.output[ix]; used=v@block; vv=float(v@v)
        if vv>1e-15:
            err=-used; err[y]+=1.; self.output[ix]=block+self.RATE*np.outer(v/vv,err); self.updates+=1
        self.ops += self.K*self.OUTPUTS + self.UNITS*self.CONTACTS + self.UNITS
    def state_hash(self):
        h=hashlib.sha256(); h.update(self.output.tobytes()); h.update(str(self.updates).encode()); return h.hexdigest()
    def fixed_hash(self):
        h=hashlib.sha256(); h.update(self.contacts.tobytes()); h.update(self.weights.tobytes()); return h.hexdigest()


def new_capacity_memory(seed, branch):
    tc, sc = branch_caps(branch)
    m = V39.Memory('TRACE-CORR', seed, trace_cap=tc, slot_cap=sc)
    m.v44_branch = branch
    return m


def probs(scores): return V39.softmax(scores)
def score_loss(scores,y): return V39.loss(scores,y)
def prob_loss(p,y): return -math.log2(max(float(p[y]),1e-300))


@dataclasses.dataclass
class Agg:
    n:int=0; total:float=0.; correct:int=0
    def add_scores(self,s,y): self.n+=1; self.total+=score_loss(s,y); self.correct+=int(int(_np.argmax(s))==y)
    def add_prob(self,p,y): self.n+=1; self.total+=prob_loss(p,y); self.correct+=int(int(_np.argmax(p))==y)
    def result(self): return {'n':self.n,'bpb':self.total/self.n if self.n else None,'accuracy':self.correct/self.n if self.n else None}


def route(packet):
    if packet['exact'] and packet['type']=='slot': return 'A'
    if packet['exact'] and packet['type']=='trace': return 'T'
    if (not packet['exact']) and packet['type']=='slot' and packet['authority']: return 'G'
    return 'F'


def get_slow_scores(memory, packet):
    if packet['type']=='slot' and packet['id'] in memory.slots: return memory.slots[packet['id']]['value']
    if packet['type']=='trace' and packet['id'] in memory.traces: return memory.traces[packet['id']]['value']
    return None


def virtual_predictions(memory, packet, fast_scores, evidence):
    r=route(packet); pf=probs(fast_scores); slow=get_slow_scores(memory,packet)
    ps=probs(slow) if slow is not None else pf
    out={'SUPER':('prob',pf)}
    # Silent traces; mature exact anchors hard slow; G uses policy.
    if r=='A':
        for p in ('SILENT-HARD','FIXED-50','LOCAL-BAYES-0'): out[p]=('prob',ps)
    elif r=='G':
        out['SILENT-HARD']=('prob',ps)
        out['FIXED-50']=('prob',0.5*pf+0.5*ps)
        e=float(evidence.get(packet['id'],0.0)); w=1.0/(1.0+2.0**(-e))
        out['LOCAL-BAYES-0']=('prob',(1-w)*pf+w*ps)
    else:
        for p in ('SILENT-HARD','FIXED-50','LOCAL-BAYES-0'): out[p]=('prob',pf)
    return r,pf,ps,out


def context_index(stream):
    idx={}
    for i,k in enumerate(stream['keys']):
        for a in (0,1,2): idx[V39.context(k,a)]={'key_id':i,'alias':a,'is_target_context':True}
    return idx


def provenance_for_contexts(contexts, ctx_index):
    ids=[]; target=False
    for c in contexts:
        d=ctx_index.get(c)
        if d is not None: target=True; ids.append(d['key_id'])
    if not target: return 'nontarget_only'
    u=set(ids)
    if len(u)==1 and len(ids)>=1: return 'target_same_key'
    if len(u)>1: return 'target_cross_key'
    return 'target_mixed_nontarget'


def same_key_candidates(memory, stream, key_id):
    """Evaluator-only audit; never used to modify lookup."""
    cs=[V39.context(stream['keys'][key_id],a) for a in (0,1)]
    traces=[c for c in cs if c in memory.traces]
    slots=set(memory.anchors[c] for c in cs if c in memory.anchors)
    return traces, slots


def semantic_counts(memory):
    c=memory.cost()
    return {'traces':len(memory.traces),'slots':len(memory.slots),'anchors':len(memory.anchors),
            'semantic_bytes':int(c['semantic_bytes'])}


def native_probe(memory, base_encoder, base, contexts_targets):
    before=memory.state_hash(); good=0
    for c,y in contexts_targets:
        z,b=base_encoder.encode(c); sb=base.scores(z,b); p=memory.lookup(c,sb)
        good += int(int(_np.argmax(p['scores']))==int(y))
    assert memory.state_hash()==before
    return good/max(1,len(contexts_targets))


def read_probe(memory, base_encoder, base, fast, contexts_targets, policy, evidence):
    before=memory.state_hash(); fh=fast.state_hash(); good=0
    for c,y in contexts_targets:
        z,b=base_encoder.encode(c); sb=base.scores(z,b); fs=fast.predict(c,count_ops=False)
        pack=memory.lookup(c,sb); _,_,_,vp=virtual_predictions(memory,pack,fs,evidence)
        pp=vp[policy][1]; good += int(int(_np.argmax(pp))==int(y))
    assert memory.state_hash()==before and fast.state_hash()==fh
    return good/max(1,len(contexts_targets))


def mature_coverage(memory, stream, ids):
    n=0
    for i in ids:
        if any(V39.context(stream['keys'][i],a) in memory.anchors for a in (0,1)): n+=1
    return n/max(1,len(list(ids)))


def checkpoint_eval(state, stream, cp, branches):
    k=stream['keys_per_wave']; wave=cp['wave']; wi=ord(wave)-65
    ids=list(range(wi*k,(wi+1)*k))
    learned=[(V39.context(stream['keys'][i],a), int(stream['labels'][i])) for i in ids for a in (0,1)]
    rows=[]
    for name in branches:
        m=state['memories'][name]; ev=state['evidence'][name]
        rows.append({'seed':state['seed'],'load':state['load'],'branch':name,'checkpoint':cp['name'],
                     'wave':wave,'exposure':cp.get('exposure'),'native_acquisition':native_probe(m,state['encoder'],state['base'],learned),
                     'mature_coverage':mature_coverage(m,stream,ids),
                     'ever_promoted':len(state['ever_promoted'][name] & set(ids))/max(1,len(ids)),
                     'trace_count':len(m.traces),'slot_count':len(m.slots),
                     'semantic_bytes':m.cost()['semantic_bytes']})
    # Cohort-heldout at end-of-wave only.
    if cp['type']=='wave':
        for name in branches:
            m=state['memories'][name]; ev=state['evidence'][name]
            for cwi in range(wi+1):
                cids=list(range(cwi*k,(cwi+1)*k))
                held=[(V39.context(stream['keys'][i],2),int(stream['labels'][i])) for i in cids]
                for pol in ('SILENT-HARD','FIXED-50'):
                    rows.append({'seed':state['seed'],'load':state['load'],'branch':name,'checkpoint':cp['name'],
                                 'wave':chr(65+cwi),'metric':'heldout_'+pol.lower(),
                                 'value':read_probe(m,state['encoder'],state['base'],state['fast'],held,pol,ev)})
    return rows


def canonical_state_hash(state):
    h=hashlib.sha256(); h.update(state['base'].state_hash().encode()); h.update(state['fast'].state_hash().encode())
    for b in sorted(state['memories']): h.update(b.encode()); h.update(state['memories'][b].state_hash().encode())
    h.update(bytes(state['history'])); h.update(str(state['row_index']).encode()); return h.hexdigest()


def checkpoint_identity(kind,seed,load,branches,smoke=False):
    return sha_json({'version':VERSION,'source':source_sha(),'design':DESIGN_SHA256,'v39':V39_SHA256,
                     'kind':kind,'seed':seed,'load':load,'branches':list(branches),'repeats':REPEATS,'smoke':smoke})


def save_checkpoint(path, identity, state):
    payload=pickle.dumps(state,protocol=5); envelope={'identity':identity,'sha256':sha_bytes(payload),'payload':payload}
    raw=zlib.compress(pickle.dumps(envelope,protocol=5),3)
    path=Path(path); prev=path.with_suffix(path.suffix+'.prev')
    if path.exists():
        with contextlib.suppress(Exception): shutil.copy2(path,prev)
    atomic_bytes(path,raw)


def load_checkpoint(path,identity):
    for p in (Path(path),Path(str(path)+'.prev')):
        if not p.exists(): continue
        try:
            e=pickle.loads(zlib.decompress(p.read_bytes()))
            if e.get('identity')!=identity: continue
            q=e['payload']
            if sha_bytes(q)!=e['sha256']: continue
            return pickle.loads(q),str(p)
        except Exception: continue
    return None,None


def initial_state(seed,load,branches):
    return {'seed':seed,'load':load,'encoder':V39.Encoder(seed,'last_fd'),'base':V39.Learner('full'),
            'fast':SuperposedLayer(seed),'memories':{b:new_capacity_memory(seed,b) for b in branches},
            'evidence':{b:{} for b in branches},'ever_promoted':{b:set() for b in branches},
            'history':bytearray(),'row_index':0,'byte_clock':0,
            'groups':{b:{p:Agg() for p in READ_POLICIES} for b in branches},
            'transitions':[],'target_audit':[],'occupancy':[],'checkpoint_rows':[],
            'event_counts':{b:collections.Counter() for b in branches},
            'slot_birth':{b:{} for b in branches},'trace_birth':{b:{} for b in branches}}


def annotate_events(state,branch,events,before_slots,before_traces,after_slots,after_traces,stream,row,pos,y,packet):
    idx=context_index(stream); now=state['byte_clock']
    new_slots=sorted(after_slots-before_slots); gone_slots=sorted(before_slots-after_slots)
    new_traces=list(after_traces-before_traces); gone_traces=list(before_traces-after_traces)
    for j in new_slots: state['slot_birth'][branch][j]=now
    for c in new_traces:
        t=state['memories'][branch].traces.get(c); state['trace_birth'][branch][c.hex()] = now if t is None else int(t['created'])
    for e in events:
        name=e['event']; state['event_counts'][branch][name]+=1
        cs=[bytes.fromhex(x) for x in e.get('contexts',[]) if x]
        if e.get('context'): cs.append(bytes.fromhex(e['context']))
        cmeta=[idx.get(c) for c in cs]
        rec={'seed':state['seed'],'load':state['load'],'branch':branch,'byte_clock':now,
             'row_number':state['row_index']+1,'byte_pos':pos,'event':name,'reason':e.get('reason'),
             'row_kind':row.get('kind'),'wave':row.get('wave'),'row_key_id':row.get('key_id'),
             'is_designated_target_byte':bool(pos==12),'outcome':int(y),
             'provenance':provenance_for_contexts(cs,idx),'contexts':[c.hex() for c in cs],
             'context_key_ids':[x.get('key_id') if x else None for x in cmeta],
             'context_aliases':[x.get('alias') if x else None for x in cmeta],
             'slot_uid_new':new_slots[0] if name in ('slot_allocation','promotion') and new_slots else None,
             'slot_uid_removed':gone_slots[0] if name=='slot_eviction' and gone_slots else None,
             'trace_context_new':new_traces[0].hex() if name=='trace_admission' and new_traces else None,
             'trace_context_removed':gone_traces[0].hex() if name=='trace_removal' and gone_traces else None,
             'source_hits':e.get('source_hits'),'source_age':e.get('source_age')}
        state['transitions'].append(rec)
        if name=='promotion':
            ids=[idx.get(c,{}).get('key_id') for c in cs]; ids=[i for i in ids if i is not None]
            if ids and len(set(ids))==1: state['ever_promoted'][branch].add(ids[0])


def process_seed(kind,seed,load,out_dir,branches,checkpoint_records=CHECKPOINT_RECORDS_DEFAULT,
                 smoke=False,engineering_reference=False,force_restart=False,pause_after=None):
    ensure_deps(False)
    out_dir=Path(out_dir); work=out_dir/'work'; work.mkdir(parents=True,exist_ok=True)
    tag=f'{kind}_L{load}_S{seed}'; ident=checkpoint_identity(kind,seed,load,branches,smoke)
    done=work/(tag+'.done.json'); ck=work/(tag+'.checkpoint.pklz')
    if done.exists() and not force_restart:
        d=json.loads(done.read_text())
        if d.get('identity')==ident: return d['result']
    state=None; resumed_from=None
    if not force_restart: state,resumed_from=load_checkpoint(ck,ident)
    if state is None: state=initial_state(seed,load,branches)
    stream=make_stream(seed,load,smoke=smoke); ctx_idx=context_index(stream)
    cps=collections.defaultdict(list)
    for cp in stream['checkpoints']: cps[cp['record_count']].append(cp)
    ref=None
    if engineering_reference:
        # Independent single-branch reference using unmodified inherited TRACE-CORR.
        ref={'memory':V39.Memory('TRACE-CORR',seed,trace_cap=TRACE_CAP,slot_cap=SLOT_CAP),
             'base':V39.Learner('full'),'encoder':V39.Encoder(seed,'last_fd'),'history':bytearray()}
    started=time.time(); checkpoint_count=0
    for ri in range(state['row_index'],len(stream['rows'])):
        row=stream['rows'][ri]
        for pos,y in enumerate(row['raw']):
            hist=state['history']; z,bank=state['encoder'].encode(bytes(hist)); base_scores=state['base'].scores(z,bank)
            fast_scores=state['fast'].predict(hist)
            packs={}
            # Target candidate audit is pre-outcome and passive.
            for b in branches:
                m=state['memories'][b]; pack=m.lookup(hist,base_scores); packs[b]=pack
                r,pf,ps,vp=virtual_predictions(m,pack,fast_scores,state['evidence'][b])
                for pol in READ_POLICIES: state['groups'][b][pol].add_prob(vp[pol][1],int(y))
                if pos==12:
                    same_t,same_s=same_key_candidates(m,stream,row['key_id']) if row.get('key_id',-1)>=0 else ([],set())
                    current_c=bytes(hist)[-12:]
                    zcur=m.address(current_c)
                    same_trace_sims=[float(m.address(c)@zcur) for c in same_t]
                    state['target_audit'].append({'seed':seed,'load':load,'branch':b,'byte_clock':state['byte_clock'],
                       'row_number':ri+1,'key_id':row.get('key_id'),'wave':row.get('wave'),'kind':row.get('kind'),'alias':row.get('alias'),
                       'exact_trace_present':bool(current_c in m.traces),'exact_slot_present':bool(current_c in m.anchors),
                       'winning_candidate_type':pack['type'],'winning_candidate_uid':pack['id'] if pack['type']=='slot' else None,
                       'winning_trace_context':pack['id'].hex() if pack['type']=='trace' and isinstance(pack['id'],bytes) else None,
                       'winning_similarity':pack['sim'],'candidate_support':pack['support'],'candidate_top1':pack['candidate_top'],
                       'candidate_correct_for_outcome':bool(pack['candidate_top']==int(y)) if pack['candidate_top'] is not None else None,
                       'base_top1':int(_np.argmax(base_scores)),'fast_top1':int(_np.argmax(fast_scores)),
                       'same_key_trace_existed':bool(same_t),'same_key_trace_max_similarity':max(same_trace_sims) if same_trace_sims else None,
                       'same_key_trace_above_tau':bool(same_trace_sims and max(same_trace_sims)>=V39.TAU),
                       'same_key_trace_won':bool(pack['type']=='trace' and pack['id'] in same_t),
                       'same_key_slot_existed':bool(same_s),'same_key_slot_won':bool(pack['type']=='slot' and pack['id'] in same_s),
                       'route':r,'outcome':int(y)})
            # Physical writes: shared BASE/FAST once, branch slow states separately.
            state['base'].observe(z,bank,int(y)); state['fast'].observe(hist,int(y))
            for b in branches:
                m=state['memories'][b]; p=packs[b]
                before_slots=set(m.slots); before_traces=set(m.traces)
                before_argmax={j:int(_np.argmax(s['value'])) for j,s in m.slots.items()}
                r=route(p); slow=get_slow_scores(m,p); pf=probs(fast_scores); ps=probs(slow) if slow is not None else pf
                if r=='G' and p['id'] is not None:
                    state['evidence'][b][p['id']]=state['evidence'][b].get(p['id'],0.)+math.log2(max(float(ps[y]),1e-300)/max(float(pf[y]),1e-300))
                ev=m.observe(p,int(y))
                after_slots=set(m.slots); after_traces=set(m.traces)
                # Lifecycle of read-only local evidence.
                for j in before_slots-after_slots: state['evidence'][b].pop(j,None)
                for j in after_slots-before_slots: state['evidence'][b].setdefault(j,0.)
                for j in before_slots & after_slots:
                    if before_argmax.get(j) != int(_np.argmax(m.slots[j]['value'])): state['evidence'][b][j]=0.
                annotate_events(state,b,ev,before_slots,before_traces,after_slots,after_traces,stream,row,pos,int(y),p)
            # Engineering baseline reference, byte-for-byte slow core only.
            if ref is not None:
                rh=ref['history']; rz,rb=ref['encoder'].encode(bytes(rh)); rs=ref['base'].scores(rz,rb)
                rp=ref['memory'].lookup(rh,rs); ref['base'].observe(rz,rb,int(y)); ref['memory'].observe(rp,int(y))
                rh.append(int(y));
                if len(rh)>12: del rh[0]
                cap=state['memories']['CAP-BASE']
                if cap.state_hash()!=ref['memory'].state_hash() or state['base'].state_hash()!=ref['base'].state_hash():
                    raise AssertionError(f'engineering CAP-BASE reference divergence at row {ri+1} pos {pos}')
            hist.append(int(y));
            if len(hist)>12: del hist[0]
            state['byte_clock']+=1
        state['row_index']=ri+1
        # Occupancy sampled each record.
        for b in branches:
            m=state['memories'][b]
            state['occupancy'].append({'seed':seed,'load':load,'branch':b,'record':ri+1,
                                       'traces':len(m.traces),'slots':len(m.slots),'semantic_bytes':m.cost()['semantic_bytes']})
        for cp in cps.get(ri+1,[]): state['checkpoint_rows'].extend(checkpoint_eval(state,stream,cp,branches))
        if (ri+1)%checkpoint_records==0 or ri+1==len(stream['rows']):
            save_checkpoint(ck,ident,state); checkpoint_count+=1
            if pause_after is not None and checkpoint_count>=pause_after:
                return {'paused':True,'seed':seed,'load':load,'kind':kind,'row_index':state['row_index']}
    # Terminal output, compact enough for one JSON per seed/load.
    terminal={}
    for b in branches:
        m=state['memories'][b]; counts=state['event_counts'][b]
        terminal[b]={'groups':{p:state['groups'][b][p].result() for p in READ_POLICIES},
                     'resources':semantic_counts(m),'event_counts':dict(counts),
                     'ever_promoted_ids':sorted(state['ever_promoted'][b]),'slow_state_hash':m.state_hash()}
    result={'kind':kind,'seed':seed,'load':load,'stream_sha256':stream['raw_sha256'],'rows':len(stream['rows']),
            'byte_events':len(stream['raw']),'branches':list(branches),'terminal':terminal,
            'checkpoint_rows':state['checkpoint_rows'],'transitions':state['transitions'],
            'target_audit':state['target_audit'],'occupancy':state['occupancy'],
            'base_hash':state['base'].state_hash(),'fast_hash':state['fast'].state_hash(),
            'fast_fixed_hash':state['fast'].fixed_hash(),'state_hash':canonical_state_hash(state),
            'resumed_from':resumed_from,'elapsed_seconds':time.time()-started,
            'baseline_independent_reference_pass':bool(engineering_reference),
            'source_sha256':source_sha(),'design_sha256':DESIGN_SHA256,'v39_sha256':V39_SHA256}
    atomic_text(done,json.dumps({'identity':ident,'result':result},default=str,separators=(',',':')))
    with contextlib.suppress(FileNotFoundError): ck.unlink()
    with contextlib.suppress(FileNotFoundError): Path(str(ck)+'.prev').unlink()
    return result


def flatten_rows(results,key):
    out=[]
    for r in results: out.extend(r.get(key,[]))
    return out


def csv_write(path,rows,fieldnames=None):
    rows=list(rows); path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    if not rows:
        atomic_text(path,''); return
    if fieldnames is None:
        fields=[]
        for r in rows:
            for k in r:
                if k not in fields: fields.append(k)
    else: fields=fieldnames
    tmp=path.with_name(path.name+'.tmp')
    with tmp.open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore'); w.writeheader(); w.writerows(rows)
    os.replace(tmp,path)


def interval(vals):
    vals=[float(x) for x in vals if x is not None and math.isfinite(float(x))]; n=len(vals)
    out={'n':n,'mean':statistics.mean(vals) if vals else None,'sd':statistics.stdev(vals) if n>1 else None,
         'low':None,'high':None,'median':statistics.median(vals) if vals else None,'q25':None,'q75':None,'values':vals}
    if vals:
        q=_np.quantile(vals,[.25,.75]); out['q25']=float(q[0]);out['q75']=float(q[1])
    if n>1:
        half=float(_student_t.ppf(.975,n-1)*statistics.stdev(vals)/math.sqrt(n));out['low']=out['mean']-half;out['high']=out['mean']+half
    return out


def extract_checkpoint_metric(result,branch,checkpoint,key):
    vals=[r for r in result['checkpoint_rows'] if r.get('branch')==branch and r.get('checkpoint')==checkpoint and key in r]
    return vals[-1].get(key) if vals else None


def held_metric(result,branch,checkpoint,cohort,policy='SILENT-HARD'):
    metric='heldout_'+policy.lower()
    vals=[r.get('value') for r in result['checkpoint_rows'] if r.get('branch')==branch and r.get('checkpoint')==checkpoint
          and r.get('wave')==cohort and r.get('metric')==metric]
    return vals[-1] if vals else None


def seed_endpoints(r,b):
    d={'acq':extract_checkpoint_metric(r,b,'after_D','native_acquisition'),
       'mature':extract_checkpoint_metric(r,b,'after_D','mature_coverage'),
       'ever_promoted':extract_checkpoint_metric(r,b,'after_D','ever_promoted'),
       'A_heldout':held_metric(r,b,'after_D','A','SILENT-HARD'),
       'A_heldout_fixed50':held_metric(r,b,'after_D','A','FIXED-50'),
       'whole_fixed50_bpb':r['terminal'][b]['groups']['FIXED-50']['bpb'],
       'whole_super_bpb':r['terminal'][b]['groups']['SUPER']['bpb']}
    lm=lifecycle_seed_metrics([r]).get((r['seed'],r['load']),{}).get(b,{})
    d.update(lm)
    # Matched delays from available wave checkpoints.
    one=[held_metric(r,b,'after_B','A'),held_metric(r,b,'after_C','B'),held_metric(r,b,'after_D','C')]
    two=[held_metric(r,b,'after_C','A'),held_metric(r,b,'after_D','B')]
    d['heldout_one_wave']=statistics.mean([x for x in one if x is not None]) if all(x is not None for x in one) else None
    d['heldout_two_wave']=statistics.mean([x for x in two if x is not None]) if all(x is not None for x in two) else None
    return d


def causal_analysis(results):
    rs=[r for r in results if r['kind']=='causal' and r['load']==CAUSAL_LOAD and set(r['branches'])==set(BRANCHES)]
    by={r['seed']:{b:seed_endpoints(r,b) for b in BRANCHES} for r in rs}
    endpoints=('acq','mature','ever_promoted','A_heldout','A_heldout_fixed50','heldout_one_wave','heldout_two_wave','trace_survival_to_alt','promotion_given_survived_eligible_alt','mature_slot_survival','whole_fixed50_bpb')
    contrasts=[]; stats={}
    for key in endpoints:
        effects={'TRACE-RELIEF_minus_CAP-BASE':[],'SLOT-RELIEF_minus_CAP-BASE':[],
                 'BOTH-RELIEF_minus_CAP-BASE':[],'factorial_trace':[],'factorial_slot':[],'interaction':[]}
        for s in sorted(by):
            y={b:by[s][b].get(key) for b in BRANCHES}
            if any(v is None for v in y.values()): continue
            effects['TRACE-RELIEF_minus_CAP-BASE'].append(y['TRACE-RELIEF']-y['CAP-BASE'])
            effects['SLOT-RELIEF_minus_CAP-BASE'].append(y['SLOT-RELIEF']-y['CAP-BASE'])
            effects['BOTH-RELIEF_minus_CAP-BASE'].append(y['BOTH-RELIEF']-y['CAP-BASE'])
            effects['factorial_trace'].append(.5*((y['TRACE-RELIEF']-y['CAP-BASE'])+(y['BOTH-RELIEF']-y['SLOT-RELIEF'])))
            effects['factorial_slot'].append(.5*((y['SLOT-RELIEF']-y['CAP-BASE'])+(y['BOTH-RELIEF']-y['TRACE-RELIEF'])))
            effects['interaction'].append(y['BOTH-RELIEF']-y['TRACE-RELIEF']-y['SLOT-RELIEF']+y['CAP-BASE'])
        stats[key]={k:interval(v) for k,v in effects.items()}
        for e,st in stats[key].items(): contrasts.append({'endpoint':key,'contrast':e,**{k:st.get(k) for k in ('n','mean','sd','low','high','median','q25','q75')}})
    # Gates / diagnostic verdict.
    # Q0/Q1: every causal seed reruns an independent frozen CAP-BASE reference;
    # capacity manipulations must also be isolated in their own tiers.
    q0=bool(len(rs)==16 and all(r.get('baseline_independent_reference_pass') for r in rs))
    violations=[]
    for r in rs:
        for b in r['branches']:
            tc,sc=branch_caps(b); ts=[x for x in r['transitions'] if x['branch']==b]; oc=[x for x in r['occupancy'] if x['branch']==b]
            if tc>=NONBINDING_CAP and any(x['event']=='trace_removal' and x.get('reason')=='capacity' for x in ts): violations.append([r['seed'],b,'trace_relief_evicted'])
            if sc>=NONBINDING_CAP and any(x['event']=='slot_eviction' and x.get('reason')=='capacity' for x in ts): violations.append([r['seed'],b,'slot_relief_evicted'])
            if tc==TRACE_CAP and any(x['traces']>TRACE_CAP for x in oc): violations.append([r['seed'],b,'trace_cap_exceeded'])
            if sc==SLOT_CAP and any(x['slots']>SLOT_CAP for x in oc): violations.append([r['seed'],b,'slot_cap_exceeded'])
    q1=not violations
    a=stats.get('acq',{}); q2=a.get('BOTH-RELIEF_minus_CAP-BASE',{}); qt=a.get('TRACE-RELIEF_minus_CAP-BASE',{}); qs=a.get('SLOT-RELIEF_minus_CAP-BASE',{})
    both_levels=[by[s]['BOTH-RELIEF']['acq'] for s in by if by[s]['BOTH-RELIEF']['acq'] is not None]
    q2pass=bool(q2.get('mean') is not None and q2['mean']>=MATERIAL and q2.get('low') is not None and q2['low']>0)
    q3pass=bool(len(both_levels)==16 and statistics.mean(both_levels)>=.90 and min(both_levels)>=.80)
    q4=bool(qt.get('mean') is not None and qt['mean']>=MATERIAL and qt.get('low') is not None and qt['low']>0)
    q5=bool(qs.get('mean') is not None and qs['mean']>=MATERIAL and qs.get('low') is not None and qs['low']>0)
    inter=a.get('interaction',{}); q6='interaction_small_or_unresolved'
    if inter.get('mean') is not None and inter.get('low') is not None and inter['mean']>=MATERIAL and inter['low']>0: q6='synergistic'
    elif inter.get('mean') is not None and inter.get('high') is not None and inter['mean']<=-MATERIAL and inter['high']<0: q6='antagonistic'
    if not q0: verdict='V44_VOID_BASELINE_REPRODUCTION'
    elif not q1: verdict='V44_VOID_INTERVENTION_ISOLATION'
    elif not q2pass: verdict='CAPACITY_NOT_PRIMARY'
    elif not q3pass: verdict='CAPACITY_CONTRIBUTORY_NOT_SUFFICIENT'
    elif q4 and not q5 and qt['mean']>=qs['mean']+MATERIAL: verdict='TRACE_PRESSURE_DOMINANT'
    elif q5 and not q4 and qs['mean']>=qt['mean']+MATERIAL: verdict='SLOT_PRESSURE_DOMINANT'
    elif not q4 and not q5 and q6=='synergistic': verdict='TIER_INTERACTION_DOMINANT'
    else: verdict='MIXED_TWO_TIER_PRESSURE'
    safety=[]
    for s in by:
        if by[s]['CAP-BASE']['A_heldout'] is not None and by[s]['BOTH-RELIEF']['A_heldout'] is not None:
            safety.append(by[s]['BOTH-RELIEF']['A_heldout']-by[s]['CAP-BASE']['A_heldout'])
    saf=interval(safety); modifier=bool(saf.get('mean') is not None and saf['mean']<-MATERIAL)
    return {'by_seed':by,'contrasts':contrasts,'stats':stats,'gates':{'Q0_baseline_reference':q0,'Q1_intervention_isolation':q1,'Q1_violations':violations,'Q2_capacity_material':q2pass,'Q3_capacity_sufficient':q3pass,
            'Q4_trace_material':q4,'Q5_slot_material':q5,'Q6_interaction':q6,'old_A_safety':saf},
            'verdict':verdict,'safety_tradeoff_modifier':modifier}



def derive_trace_survival(results):
    """One row per evaluator-target trace admission, with first alternate-rendering opportunity."""
    rows=[]
    for r in results:
        audits=r.get('target_audit',[]); trans=r.get('transitions',[])
        # Target opportunity sequence indexed by branch/key.
        by_bk=collections.defaultdict(list)
        for a in audits:
            if a.get('key_id') is not None and a.get('kind')=='acquisition': by_bk[(a['branch'],int(a['key_id']))].append(a)
        for k in by_bk: by_bk[k].sort(key=lambda x:x['byte_clock'])
        # Removal/promotion lookups by source context.
        for e in trans:
            if e.get('event')!='trace_admission' or not e.get('is_designated_target_byte'):
                continue
            ids=[x for x in (e.get('context_key_ids') or []) if x is not None]
            aliases=[x for x in (e.get('context_aliases') or []) if x is not None]
            if not ids: continue
            key=int(ids[0]); alias=int(aliases[0]) if aliases else None; b=e['branch']; t0=e['byte_clock']
            alt=None
            for a in by_bk.get((b,key),[]):
                if a['byte_clock']>t0 and a.get('alias')!=alias:
                    alt=a; break
            ctx=(e.get('contexts') or [None])[0]
            rem=[x for x in trans if x['branch']==b and x.get('event')=='trace_removal' and ctx in (x.get('contexts') or []) and x['byte_clock']>=t0]
            rem=min(rem,key=lambda x:x['byte_clock']) if rem else None
            promoted=bool(rem and rem.get('reason')=='promotion')
            rows.append({'kind':r['kind'],'seed':r['seed'],'load':r['load'],'branch':b,'key_id':key,'admitted_alias':alias,
                         'admission_clock':t0,'first_alt_clock':None if alt is None else alt['byte_clock'],
                         'survived_to_first_alt':None if alt is None else bool(rem is None or rem['byte_clock']>=alt['byte_clock']),
                         'same_key_trace_existed_at_alt':None if alt is None else alt.get('same_key_trace_existed'),
                         'same_key_trace_above_tau_at_alt':None if alt is None else alt.get('same_key_trace_above_tau'),
                         'same_key_trace_won_at_alt':None if alt is None else alt.get('same_key_trace_won'),
                         'candidate_correct_at_alt':None if alt is None else alt.get('candidate_correct_for_outcome'),
                         'promoted_eventually':promoted,'removal_clock':None if rem is None else rem['byte_clock'],
                         'removal_reason':None if rem is None else rem.get('reason')})
    return rows


def derive_slot_survival(results):
    """One row per pure target promotion/slot birth with later capacity-eviction status."""
    rows=[]
    for r in results:
        trans=r.get('transitions',[])
        terminal=r.get('terminal',{})
        for e in trans:
            if e.get('event')!='promotion' or e.get('slot_uid_new') is None: continue
            ids=[x for x in (e.get('context_key_ids') or []) if x is not None]
            if not ids or len(set(ids))!=1: continue
            j=e['slot_uid_new']; b=e['branch']; t0=e['byte_clock']; key=int(ids[0])
            ev=[x for x in trans if x['branch']==b and x.get('event')=='slot_eviction' and x.get('slot_uid_removed')==j and x['byte_clock']>=t0]
            ev=min(ev,key=lambda x:x['byte_clock']) if ev else None
            rows.append({'kind':r['kind'],'seed':r['seed'],'load':r['load'],'branch':b,'key_id':key,'slot_uid':j,
                         'promotion_clock':t0,'evicted':bool(ev),'eviction_clock':None if ev is None else ev['byte_clock'],
                         'eviction_reason':None if ev is None else ev.get('reason'),
                         'survived_terminal':not bool(ev)})
    return rows


def lifecycle_seed_metrics(results):
    tr=derive_trace_survival(results); sl=derive_slot_survival(results)
    out=collections.defaultdict(dict)
    groups=collections.defaultdict(list)
    for x in tr: groups[(x['seed'],x['load'],x['branch'])].append(x)
    sgroups=collections.defaultdict(list)
    for x in sl: sgroups[(x['seed'],x['load'],x['branch'])].append(x)
    keys=set(groups)|set(sgroups)
    for key in keys:
        xs=groups.get(key,[]); ys=sgroups.get(key,[])
        elig=[x for x in xs if x.get('first_alt_clock') is not None]
        survived=[x for x in elig if x.get('survived_to_first_alt')]
        eligible_candidate=[x for x in survived if x.get('same_key_trace_above_tau_at_alt')]
        k=(key[0],key[1]); b=key[2]
        out[k][b]={
            'trace_survival_to_alt': (sum(bool(x.get('survived_to_first_alt')) for x in elig)/len(elig) if elig else None),
            'promotion_given_survived_eligible_alt': (sum(bool(x.get('promoted_eventually')) for x in eligible_candidate)/len(eligible_candidate) if eligible_candidate else None),
            'mature_slot_survival': (sum(bool(x.get('survived_terminal')) for x in ys)/len(ys) if ys else None),
        }
    return out

def export_outputs(out_dir,results,stage):
    out=Path(out_dir); out.mkdir(parents=True,exist_ok=True)
    scientific=[r for r in results if r.get('kind') in ('causal','forensic')]
    engineering=[r for r in results if r.get('kind')=='engineering']
    table_results = scientific if scientific else engineering
    atomic_text(out/'PROTOCOL.md',design_text())
    manifest={'version':VERSION,'source_sha256':source_sha(),'design_sha256':DESIGN_SHA256,'embedded_v39_sha256':V39_SHA256,
              'stage':stage,'science_seeds':list(SCIENCE_SEEDS),'causal_load':CAUSAL_LOAD,'forensic_loads':list(FORENSIC_LOADS),
              'repeats':REPEATS,'branches':list(BRANCHES),'caps':{b:branch_caps(b) for b in BRANCHES},
              'environment':{'python':sys.version,'numpy':_np.__version__,'platform':platform.platform(),'machine':platform.machine(),
                             'blas_threads':1},'completed_science':[(r['kind'],r['load'],r['seed']) for r in scientific],
              'completed_engineering':[(r['kind'],r['load'],r['seed']) for r in engineering]}
    write_json(out/'MANIFEST.json',manifest)
    cp=flatten_rows(table_results,'checkpoint_rows'); csv_write(out/'CHECKPOINT_ACQUISITION.csv',cp)
    csv_write(out/'MATURE_COVERAGE.csv',[r for r in cp if 'mature_coverage' in r])
    csv_write(out/'EVER_PROMOTED.csv',[r for r in cp if 'ever_promoted' in r])
    csv_write(out/'COHORT_RETENTION.csv',[r for r in cp if r.get('metric','').startswith('heldout_')])
    transitions=flatten_rows(table_results,'transitions'); csv_write(out/'CONSOLIDATION_PIPELINE.csv',transitions)
    # More focused lifecycle tables.
    trace_survival=derive_trace_survival(table_results); slot_survival=derive_slot_survival(table_results)
    csv_write(out/'TRACE_SURVIVAL.csv',trace_survival)
    csv_write(out/'SLOT_SURVIVAL.csv',slot_survival)
    target_audit=flatten_rows(table_results,'target_audit')
    csv_write(out/'TARGET_CANDIDATE_AUDIT.csv',target_audit)
    # Compressed machine-readable event payloads requested by the locked design.
    _np.savez_compressed(out/'TRANSITION_EVENTS.npz', records=_np.asarray([json.dumps(x,separators=(',',':'),default=str) for x in transitions],dtype=str))
    _np.savez_compressed(out/'TARGET_CANDIDATE_AUDIT.npz', records=_np.asarray([json.dumps(x,separators=(',',':'),default=str) for x in target_audit],dtype=str))
    occ=flatten_rows(table_results,'occupancy')
    with gzip.open(out/'OCCUPANCY_CURVES.csv.gz','wt',newline='') as f:
        if occ:
            fields=list(occ[0]); w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(occ)
    ecology=[]; readrows=[]
    for r in table_results:
        for b,t in r['terminal'].items():
            ecology.append({'kind':r['kind'],'seed':r['seed'],'load':r['load'],'branch':b,**t['resources'],
                            **{f'event_{k}':v for k,v in t['event_counts'].items()}})
            for p,g in t['groups'].items(): readrows.append({'kind':r['kind'],'seed':r['seed'],'load':r['load'],'branch':b,'policy':p,**g})
    csv_write(out/'RESOURCE_ECOLOGY.csv',ecology); csv_write(out/'READ_POLICY_SUMMARY.csv',readrows)
    stateaudit={'results':[{'kind':r['kind'],'seed':r['seed'],'load':r['load'],'stream_sha256':r['stream_sha256'],
                            'base_hash':r['base_hash'],'fast_hash':r['fast_hash'],'state_hash':r['state_hash'],
                            'baseline_independent_reference_pass':r.get('baseline_independent_reference_pass',False)} for r in table_results]}
    write_json(out/'STATE_HASH_AUDIT.json',stateaudit)
    firewall={'shared_base_fast_by_seed':True,'notes':'BASE and FAST are single shared objects inside each causal seed. Slow admission receives BASE scores only.',
              'branches':{b:{'trace_cap':branch_caps(b)[0],'slot_cap':branch_caps(b)[1]} for b in BRANCHES}}
    # Conservation is summarized from terminal counts and current states; raw transition log remains available for exact checks.
    cons=[]
    for r in table_results:
        for b,t in r['terminal'].items():
            ec=t['event_counts']; cons.append({'kind':r['kind'],'seed':r['seed'],'load':r['load'],'branch':b,
                'trace_admissions':ec.get('trace_admission',0),'trace_removals':ec.get('trace_removal',0),
                'slot_allocations':ec.get('slot_allocation',0),'slot_evictions':ec.get('slot_eviction',0),
                'terminal_traces':t['resources']['traces'],'terminal_slots':t['resources']['slots']})
    for x in cons:
        x['trace_conservation_pass']=(x['trace_admissions']-x['trace_removals']==x['terminal_traces'])
        x['slot_conservation_pass']=(x['slot_allocations']-x['slot_evictions']==x['terminal_slots'])
    write_json(out/'EVENT_CONSERVATION_AUDIT.json',{'pass':all(x['trace_conservation_pass'] and x['slot_conservation_pass'] for x in cons),'rows':cons})
    # Capacity-isolation checks from the observed trajectories.
    violations=[]
    for r in table_results:
        for b in r['branches']:
            trcap,slcap=branch_caps(b)
            ts=[x for x in r['transitions'] if x['branch']==b]
            occb=[x for x in r['occupancy'] if x['branch']==b]
            if trcap>=NONBINDING_CAP and any(x['event']=='trace_removal' and x.get('reason')=='capacity' for x in ts): violations.append([r['seed'],r['load'],b,'trace_relief_evicted'])
            if slcap>=NONBINDING_CAP and any(x['event']=='slot_eviction' and x.get('reason')=='capacity' for x in ts): violations.append([r['seed'],r['load'],b,'slot_relief_evicted'])
            if trcap==TRACE_CAP and any(x['traces']>TRACE_CAP for x in occb): violations.append([r['seed'],r['load'],b,'trace_cap_exceeded'])
            if slcap==SLOT_CAP and any(x['slots']>SLOT_CAP for x in occb): violations.append([r['seed'],r['load'],b,'slot_cap_exceeded'])
    firewall['violations']=violations; firewall['pass']=not violations
    write_json(out/'BRANCH_FIREWALL_AUDIT.json',firewall)
    if engineering:
        write_json(out/'ENGINEERING_AUDIT.json',{'completed':len(engineering),'all_independent_CAP_BASE_references_pass':all(r.get('baseline_independent_reference_pass') for r in engineering),'results':[{'seed':r['seed'],'load':r['load'],'state_hash':r['state_hash']} for r in engineering]})
    analysis=causal_analysis(scientific) if any(r['kind']=='causal' for r in scientific) else None
    if analysis:
        csv_write(out/'CAUSAL_CONTRASTS.csv',analysis['contrasts'])
        # concise report
        L=['# V44 results — causal capacity decomposition','',f"**Verdict:** `{analysis['verdict']}`" + (' + `CAPACITY_RESCUE_WITH_SAFETY_TRADEOFF`' if analysis['safety_tradeoff_modifier'] else ''),'',
           'This round diagnoses resource pressure; it does not test a deployable repair.','',
           '## Gates','',f"- Q0 independent CAP-BASE reproduction: **{analysis['gates']['Q0_baseline_reference']}**",
           f"- Q1 intervention isolation: **{analysis['gates']['Q1_intervention_isolation']}**",
           f"- Q2 capacity materially contributes: **{analysis['gates']['Q2_capacity_material']}**",
           f"- Q3 removing both caps restores acquisition criterion: **{analysis['gates']['Q3_capacity_sufficient']}**",
           f"- Q4 trace pressure material: **{analysis['gates']['Q4_trace_material']}**",
           f"- Q5 mature-slot pressure material: **{analysis['gates']['Q5_slot_material']}**",
           f"- Q6 interaction: **{analysis['gates']['Q6_interaction']}**",'',
           '## Primary acquisition contrasts','', '| contrast | mean | 95% interval |','|---|---:|---:|']
        for row in analysis['contrasts']:
            if row['endpoint']=='acq': L.append(f"| {row['contrast']} | {row['mean']:+.4f} | [{row['low']:+.4f}, {row['high']:+.4f}] |" if row['low'] is not None else f"| {row['contrast']} | {row['mean']} | -- |")
        L += ['', 'See `CAUSAL_CONTRASTS.csv`, lifecycle tables, and `PROTOCOL.md` for the locked interpretation rules.']
        atomic_text(out/'SUMMARY.md','\n'.join(L)+'\n'); write_json(out/'REPORT.json',analysis)
    else:
        atomic_text(out/'SUMMARY.md','# V44 forensic replay\n\nNo causal panel was requested in this invocation.\n')
        write_json(out/'REPORT.json',{'stage':stage,'causal_analysis':None})
    # Artifact hashes last, excluding itself.
    hashes={p.name:sha_bytes(p.read_bytes()) for p in out.iterdir() if p.is_file() and p.name!='ARTIFACT_HASHES.json'}
    write_json(out/'ARTIFACT_HASHES.json',hashes)



def package_results(out_dir):
    out=Path(out_dir); target=out.parent/(out.name+'_upload.zip')
    tmp=target.with_suffix('.tmp.zip')
    with zipfile.ZipFile(tmp,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as z:
        for p in sorted(out.iterdir()):
            if not p.is_file() or p.name.startswith('.'): continue
            z.write(p,arcname=p.name)
    os.replace(tmp,target)
    return target


def status(out_dir):
    out=Path(out_dir); work=out/'work'; done=[]; checkpoints=[]
    if work.exists():
        for p in work.glob('*.done.json'):
            with contextlib.suppress(Exception):
                r=json.loads(p.read_text())['result']; done.append((r['kind'],r['load'],r['seed']))
        checkpoints=[p.name for p in work.glob('*.checkpoint.pklz')]
    causal=len([x for x in done if x[0]=='causal'])
    forensic=len([x for x in done if x[0]=='forensic'])
    engineering=len([x for x in done if x[0]=='engineering'])
    return {'out_dir':str(out),'engineering_completed':engineering,'causal_completed':causal,'causal_expected':16,
            'forensic_completed':forensic,'forensic_expected_in_stage_all':48,'active_checkpoints':sorted(checkpoints),
            'upload_zip':str(out.parent/(out.name+'_upload.zip')) if (out.parent/(out.name+'_upload.zip')).exists() else None}

def self_test():
    ensure_deps(False); np=_np; checks={}
    # Embedded provenance and stream structure.
    checks['embedded_v39_sha256']=V39_SHA256
    s=make_stream(944901,64,smoke=True); assert all(len(r['raw'])==14 for r in s['rows']); checks['stream_rows']=len(s['rows'])
    ms={b:new_capacity_memory(944901,b) for b in BRANCHES}
    # All start equal semantically apart from caps/branch label.
    h=[m.state_hash() for m in ms.values()]; assert len(set(h))==1; checks['branch_start_equal']=True
    # Force a small trace overflow using exact inherited logic on a fixture copy.
    a=new_capacity_memory(944902,'CAP-BASE'); a.trace_cap=2
    base=np.zeros(256); base[0]=1
    for q,y in [(b'aaaaaaaaaaaa',3),(b'bbbbbbbbbbbb',4),(b'cccccccccccc',5)]:
        p=a.lookup(q,base); ev=a.observe(p,y)
    assert len(a.traces)<=2 and any(e['event']=='trace_removal' and e.get('reason')=='capacity' for e in ev); checks['trace_overflow_fixture']=True
    # Read policy is pure.
    m=new_capacity_memory(944903,'CAP-BASE'); fs=np.zeros(256); fs[1]=1.; p=m.lookup(b'abcdefghijkl',base); before=m.state_hash(); virtual_predictions(m,p,fs,{}); assert before==m.state_hash(); checks['read_policy_pure']=True
    # Fast layer deterministic.
    f1=SuperposedLayer(944904); f2=SuperposedLayer(944904); assert f1.fixed_hash()==f2.fixed_hash(); checks['fast_fixed_deterministic']=True
    # Tiny interruption/resume smoke: one checkpoint, resume, compare to uninterrupted.
    td=Path(tempfile.mkdtemp(prefix='v44-selftest-'))
    try:
        p1=process_seed('selftest',944905,64,td,BRANCHES,checkpoint_records=1,smoke=True,pause_after=1,force_restart=True)
        assert p1.get('paused')
        r1=process_seed('selftest',944905,64,td,BRANCHES,checkpoint_records=1,smoke=True)
        td2=td/'fresh'; r2=process_seed('selftestfresh',944905,64,td2,BRANCHES,checkpoint_records=9999,smoke=True,force_restart=True)
        # kind participates in external identity, not trajectory. Compare physical/terminal content.
        assert r1['base_hash']==r2['base_hash'] and r1['fast_hash']==r2['fast_hash']
        for b in BRANCHES: assert r1['terminal'][b]['slow_state_hash']==r2['terminal'][b]['slow_state_hash']
        checks['resume_equivalence']=True
    finally: shutil.rmtree(td,ignore_errors=True)
    return checks


def acquire_run_lock(out_dir):
    p=Path(out_dir); p.mkdir(parents=True,exist_ok=True); f=(p/'.v44_runner.lock').open('a+')
    try: fcntl.flock(f.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BlockingIOError: raise SystemExit(f'Another V44 top-level runner is already using {out_dir}')
    return f


def worker_entry(kwargs):
    ensure_deps(False); return process_seed(**kwargs)


def run_jobs(jobs,workers):
    if workers<=1: return [worker_entry(j) for j in jobs]
    # spawn-safe ProcessPoolExecutor; no fork-dependent state.
    import multiprocessing as mp
    ctx=mp.get_context('spawn')
    out=[]
    with concurrent.futures.ProcessPoolExecutor(max_workers=workers,mp_context=ctx) as ex:
        fut={ex.submit(worker_entry,j):(j['kind'],j['load'],j['seed']) for j in jobs}
        for f in concurrent.futures.as_completed(fut):
            key=fut[f]; r=f.result(); out.append(r); print(f'  completed {key}',flush=True)
    return out


def collect_existing(out_dir):
    results=[]
    for p in sorted((Path(out_dir)/'work').glob('*.done.json')) if (Path(out_dir)/'work').exists() else []:
        try: results.append(json.loads(p.read_text())['result'])
        except Exception: pass
    return results


def main(argv=None):
    ap=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--install-deps',action='store_true')
    ap.add_argument('--self-test',action='store_true')
    ap.add_argument('--status',action='store_true')
    ap.add_argument('--engineering',action='store_true')
    ap.add_argument('--stage',choices=('causal','forensic','all'),default='causal')
    ap.add_argument('--out-dir',type=Path,default=Path('v44_results'))
    ap.add_argument('--workers',type=int,default=4)
    ap.add_argument('--checkpoint-records',type=int,default=CHECKPOINT_RECORDS_DEFAULT)
    ap.add_argument('--seeds',type=int,nargs='*',help='Override science seed list (engineering/non-preregistered unless exact roster).')
    ap.add_argument('--smoke',action='store_true')
    ap.add_argument('--force-restart',action='store_true')
    args=ap.parse_args(argv)
    ensure_deps(args.install_deps)
    if args.self_test:
        print(json.dumps(self_test(),indent=2)); return 0
    if args.status:
        print(json.dumps(status(args.out_dir),indent=2)); return 0
    lock=acquire_run_lock(args.out_dir)
    try:
        if args.engineering:
            jobs=[{'kind':'engineering','seed':s,'load':256,'out_dir':args.out_dir,'branches':BRANCHES,
                   'checkpoint_records':args.checkpoint_records,'smoke':args.smoke,'engineering_reference':True,
                   'force_restart':args.force_restart} for s in ENGINEERING_SEEDS]
            print(f'V44 engineering: {len(jobs)} load-256 seeds, four branches + independent CAP-BASE reference',flush=True)
            run_jobs(jobs,min(args.workers,2)); results=collect_existing(args.out_dir); export_outputs(args.out_dir,results,'engineering'); package_results(args.out_dir)
            return 0
        seeds=tuple(args.seeds) if args.seeds else SCIENCE_SEEDS
        jobs=[]
        if args.stage in ('causal','all'):
            jobs += [{'kind':'causal','seed':s,'load':CAUSAL_LOAD,'out_dir':args.out_dir,'branches':BRANCHES,
                      'checkpoint_records':args.checkpoint_records,'smoke':args.smoke,'engineering_reference':True,
                      'force_restart':args.force_restart} for s in seeds]
        if args.stage in ('forensic','all'):
            loads=FORENSIC_LOADS if args.stage=='forensic' else tuple(l for l in FORENSIC_LOADS if l!=CAUSAL_LOAD)
            jobs += [{'kind':'forensic','seed':s,'load':l,'out_dir':args.out_dir,'branches':('CAP-BASE',),
                      'checkpoint_records':args.checkpoint_records,'smoke':args.smoke,'engineering_reference':False,
                      'force_restart':args.force_restart} for l in loads for s in seeds]
        print(f'V44 {args.stage}: {len(jobs)} seed/load jobs; workers={args.workers}; M3 BLAS threads=1',flush=True)
        run_jobs(jobs,args.workers)
        results=collect_existing(args.out_dir); export_outputs(args.out_dir,results,args.stage); z=package_results(args.out_dir)
        print(f'Wrote {args.out_dir}/SUMMARY.md and {z}',flush=True)
        return 0
    finally:
        with contextlib.suppress(Exception): fcntl.flock(lock.fileno(),fcntl.LOCK_UN); lock.close()

if __name__=='__main__': raise SystemExit(main())
